// sends the three.js constructor params with the elements.

import { serve } from 'ren-core/worker';
import { CONSTRUCT } from 'ren-three';
import { Scene } from './scene.jsx';

serve(() => <Scene />, { id: 'three-worker', construct: CONSTRUCT });
